+async function saveExport(path, data) {
+  const controller = new AbortController();
+  await Promise.race([
+    writeFile(path, data, { signal: controller.signal }),
+    new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 100)),
+  ]);
+}

